    # For simplicity, let's assume similar features mean they are not empty and have the same length
    if isinstance(MAPID, str) and isinstance(DetailURL, str):
        if MAPID and DetailURL and len(MAPID) == len(DetailURL):
            return 1
        else:
            return 0
    elif isinstance(MAPID, dict) and isinstance(DetailURL, dict):
        try:
            mapid = json.dumps(MAPID, sort_keys=True)
            detailurl = json.dumps(DetailURL, sort_keys=True)
            if mapid and detailurl and len(mapid) == len(detailurl):
                return 1
            else:
                return 0
        except Exception as e:
            return 0
    else:
        return 0

